#[path="custom_final_next_wave_support.rs"] mod source_support;
use ironsmith::{CardDefinition,GameState,ObjectId,PlayerId,Zone};use ironsmith::decision::SelectFirstDecisionMaker;
const A:PlayerId=PlayerId(0);const B:PlayerId=PlayerId(1);
fn source()->[CardDefinition;2]{let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/revolution-solo-officer-source.json")).unwrap();source_support::definitions(&fixture["mechanics"][0]["representative_cards"][0]).unwrap()}
fn body(token:bool,identity:bool)->CardDefinition {let builder=ironsmith_compiler::CardDefinitionBuilder::new(ironsmith_compiler::ids::CardId::new(),"Entry witness");let builder=if token{builder.token()}else{builder};let builder=if identity{builder.with_custom_keyword("undercover")}else{builder};ironsmith_compiler_runtime::compile_builder_to_runtime_definition(builder,"Type: Creature — Elf\nMana cost: {0}\nPower/Toughness: 5/6\nFlying\nWhen this creature enters, draw a card.",false).unwrap()}
fn enter(game:&mut GameState,id:ObjectId)->ObjectId{let result=game.move_object_with_etb_processing_with_dm(id,Zone::Battlefield,&mut SelectFirstDecisionMaker).unwrap();assert!(!result.pending);result.original.into_result().unwrap().new_id}
#[test]
fn exact_source_replaces_uncast_nontoken_arrivals_before_their_etb_abilities_exist(){for definition in source(){for zone in [Zone::Hand,Zone::Graveyard,Zone::Exile]{for controller in [A,B]{
 let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.create_object_from_definition(&definition,A,Zone::Battlefield);let incoming=game.create_object_from_definition(&body(false,false),controller,zone);let arrival=enter(&mut game,incoming);
 assert!(game.is_face_down(arrival));assert_eq!(game.calculated_power(arrival),Some(2));assert_eq!(game.calculated_toughness(arrival),Some(2));let chars=game.calculated_characteristics(arrival).unwrap();assert!(chars.abilities.is_empty(),"entry grants no abilities to this characteristicless face-down creature");assert!(chars.subtypes.is_empty());assert!(!game.is_manifested(arrival));assert!(!game.is_cloaked(arrival));assert!(!game.has_printed_cost_turn_face_up_permission(arrival));
 let mut queue=ironsmith::triggers::TriggerQueue::new();ironsmith::game_loop::drain_pending_trigger_events_with_dm(&mut game,&mut queue,&mut SelectFirstDecisionMaker).unwrap();assert!(queue.entries.is_empty(),"the entrant's printed ETB ability never triggered face-up");
 }}}}
#[test]
fn tokens_actual_undercover_identity_and_noncreatures_are_not_modified(){for definition in source(){for (token,identity) in [(true,false),(false,true)]{
 let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.create_object_from_definition(&definition,A,Zone::Battlefield);let incoming=game.create_object_from_definition(&body(token,identity),A,Zone::Hand);let arrival=enter(&mut game,incoming);assert!(!game.is_face_down(arrival));assert_eq!(game.calculated_power(arrival),Some(5));
 }let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.create_object_from_definition(&definition,A,Zone::Battlefield);let artifact=ironsmith_compiler_runtime::compile_to_runtime_definition("Artifact witness","Type: Artifact",false).unwrap();let old=game.create_object_from_definition(&artifact,A,Zone::Graveyard);let arrival=enter(&mut game,old);assert!(!game.is_face_down(arrival));}}
#[test]
fn real_cast_receipt_prevents_entry_replacement(){for definition in source(){
 use ironsmith::decision::{compute_legal_actions,LegalAction};use ironsmith::game_loop::{PriorityLoopState,PriorityResponse,apply_priority_response_with_dm,apply_decision_context_with_dm};
 let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.turn.active_player=A;game.turn.priority_player=Some(A);game.turn.phase=ironsmith::game_state::Phase::FirstMain;game.turn.step=None;game.create_object_from_definition(&definition,A,Zone::Battlefield);let incoming=game.create_object_from_definition(&body(false,false),A,Zone::Hand);let stable=game.object(incoming).unwrap().stable_id;
 let action=compute_legal_actions(&game,A).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==incoming)).unwrap();let mut state=PriorityLoopState::new(2);let mut queue=ironsmith::triggers::TriggerQueue::new();let mut dm=SelectFirstDecisionMaker;let mut progress=apply_priority_response_with_dm(&mut game,&mut queue,&mut state,&PriorityResponse::PriorityAction(action),&mut dm).unwrap();for _ in 0..64{if !state.has_pending_action(){break;}let ironsmith::GameProgress::NeedsDecisionCtx(ctx)=progress else{panic!("casting decision")};progress=apply_decision_context_with_dm(&mut game,&mut queue,&mut state,&ctx,&mut dm).unwrap();}assert!(!state.has_pending_action());ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();let arrival=game.find_object_by_stable_id(stable).unwrap();assert!(!game.is_face_down(arrival));assert_eq!(game.calculated_power(arrival),Some(5));
 }}
